mapper.select:
select att_review_id as attReviewId, att_id as attId, user_id as userId, att_review_comment as attReviewComment, att_rating as attRating, att_time as attTime
from attraction_review
where att_id = #{attId};

select att_review_id as attReviewId, att_id as attId, user_id as userId, att_review_comment as attReviewComment, att_rating as attRating, att_time as attTime
from attraction_review
where att_review_id = #{attReviewId};

select count(*)
from attraction_review
where user_id = #{userId}
	and att_id = #{attId}
	and date(att_time) = curdate();

mapper.update:
update attraction_review
set att_review_comment = #{attReviewComment},
    att_rating = #{attRating}
where att_review_id = #{attReviewId};
